"""Write CREDITS.md: every third-party map, dataset and picture used on the site, with author and licence.

Generated from data/images.json and data/wiki.json, so run it again after adding pictures:
  python site/tools/credits.py
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

HEAD = """# Credits

The site uses openly licensed material from the sources below. Each item keeps its own licence;
our own work is MIT-0 (code) and CC0 (texts, AI illustrations) – see LICENSE and LICENSE-content.

*This file is generated by `site/tools/credits.py` – don't edit it by hand.*

## Maps and data
| What | Source | Licence |
|---|---|---|
| Historical map images (`site/maps/`): 3rd military survey, TM25, ZM50 | © GKÚ Bratislava / ÚGKK SR, [ZBGIS](https://zbgis.skgeodesy.sk) | [CC BY 4.0](https://creativecommons.org/licenses/by/4.0/) |
| Drawn map (`data/layers.json`): rivers, water, villages, county border | © [OpenStreetMap](https://www.openstreetmap.org/copyright) contributors | [ODbL 1.0](https://opendatacommons.org/licenses/odbl/1-0/) |
| Elevation used to derive marsh and upland zones | [AWS Terrain Tiles](https://registry.opendata.aws/terrain-tiles/) (Mapzen; includes SRTM, USGS and other public sources) | see the [attribution list](https://github.com/tilezen/joerd/blob/master/docs/attribution.md) |
| Wikipedia preview texts (`data/wiki.json`) | Wikipedia (sk, cs, en) contributors | [CC BY-SA 4.0](https://creativecommons.org/licenses/by-sa/4.0/) |
| Fonts: Cormorant Garamond, Source Sans 3, IBM Plex Mono | Google Fonts | [SIL Open Font License](https://openfontlicense.org) |

"""


def cell(s):
    return str(s or "").replace("|", "\\|").replace("\n", " ")


def main():
    images = json.loads((ROOT / "data" / "images.json").read_text(encoding="utf-8"))
    wiki = json.loads((ROOT / "data" / "wiki.json").read_text(encoding="utf-8"))
    out = [HEAD, "## Gallery pictures (`site/img/`)", "| File | Caption | Author | Licence | Source |", "|---|---|---|---|---|"]
    ai = []
    for im in images:
        c = im["credit"]
        if im["kind"] == "ai":
            ai.append(im)
            continue
        lic = f"[{cell(c['license'])}]({c['licenseUrl']})" if c.get("licenseUrl") else cell(c["license"])
        src = f"[{cell(c.get('site') or 'source')}]({c['url']})" if c.get("url") else cell(c.get("site"))
        out.append(f"| `{im['id']}.jpg` | {cell(im['caption']['en'])} | {cell(c['author'])} | {lic} | {src} |")
    out += ["", "## AI illustrations", "Generated with Google Gemini (`gemini-3-pro-image`) from the prompts in `data/ai_prompts.json`, "
            "marked \"AI\" on the site. Released under CC0 like the rest of our content.", ""]
    out += [f"- `{im['id']}.jpg` – {cell(im['caption']['en'])}" for im in ai]
    out += ["", "## Wikipedia preview pictures (`site/wiki/`)", "| File | Commons file | Author | Licence |", "|---|---|---|---|"]
    for key, w in sorted(wiki.items()):
        c = w.get("imgCredit")
        if w.get("img") and c:
            out.append(f"| `{w['img']}` | [{cell(c['file'])}]({c['url']}) | {cell(c.get('author'))} | {cell(c.get('license'))} |")
    out += ["", "## Linked only (not copied)", "Old postcards from [Hungaricana](https://gallery.hungaricana.hu) are linked from the page; "
            "their publication requires the holding museums' permission.", ""]
    (ROOT / "CREDITS.md").write_text("\n".join(out), encoding="utf-8")
    print(f"CREDITS.md: {len(images) - len(ai)} pictures, {len(ai)} AI, {sum(1 for w in wiki.values() if w.get('imgCredit'))} preview pictures")


if __name__ == "__main__":
    main()
